package ru.meguboom.mobile;
import android.content.*;import android.os.*;import com.google.android.gms.auth.api.identity.*;import com.google.android.gms.common.api.Scope;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Native persisted progress, shared by Activity and foreground service, with silent background auth. */
final class NativeProgress {
 static final List<Scope> SCOPES=Arrays.asList(new Scope("https://www.googleapis.com/auth/drive.readonly"),new Scope("https://www.googleapis.com/auth/drive.appdata"));
 private static NativeProgress instance;static synchronized NativeProgress get(Context c){if(instance==null)instance=new NativeProgress(c.getApplicationContext());return instance;}
 final Context context;final SharedPreferences meta;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService io=Executors.newSingleThreadExecutor();final Map<String,String> aliases=new HashMap<>();
 final List<Runnable> waiters=new ArrayList<>();final String device;volatile String account;String status="offline",error="";long lastAttempt=0,lastSuccess=0;boolean running=false;volatile int generation=0;JSONObject own,merged;
 NativeProgress(Context c){context=c;meta=c.getSharedPreferences("progress-sync",0);String id=meta.getString("deviceId","");if(!ProgressRecords.uuid(id)){id=UUID.randomUUID().toString();meta.edit().putString("deviceId",id).apply();}device=id;account=meta.getString("account","");load();}
 SharedPreferences partition(){return context.getSharedPreferences("progress-sync-"+(account.isEmpty()?"unassigned":account),0);}
 synchronized void load(){SharedPreferences p=partition();try{own=new JSONObject(p.getString("own","{}"));merged=new JSONObject(p.getString("merged","{}"));}catch(Exception ignored){own=new JSONObject();merged=new JSONObject();}lastSuccess=p.getLong("lastSuccess",0);}
 synchronized void persist(){partition().edit().putString("own",own.toString()).putString("merged",merged.toString()).putLong("lastSuccess",lastSuccess).apply();}
 synchronized void register(JSONObject b){String file=ProgressRecords.fileId(b),id=b.optString("id");if(file.isEmpty())return;aliases.put(id,file);aliases.put("drive-"+file,file);String downloaded=b.optString("downloadOf");if(!downloaded.isEmpty())aliases.put(downloaded,file);if(!account.isEmpty()&&account.equals(meta.getString("legacyOwner",""))&&!merged.has(file)){SharedPreferences old=context.getSharedPreferences("progress",0);boolean done=old.getStringSet("completedIds",Collections.emptySet()).contains(id)||old.getStringSet("completedIds",Collections.emptySet()).contains("drive-"+file);long pos=old.getInt(id,old.getInt("drive-"+file,0));if(pos>0||done)edit(file,pos,0,done,1);}}
 synchronized String canonical(String id){String known=aliases.get(id);if(known!=null)return known;if(id!=null&&id.startsWith("drive-")&&ProgressRecords.validId(id.substring(6)))return id.substring(6);return "";}
 synchronized JSONObject record(String id){JSONObject r=merged.optJSONObject(canonical(id));try{return r==null?new JSONObject():new JSONObject(r.toString());}catch(Exception e){return new JSONObject();}}
 synchronized long position(String id){JSONObject r=record(id);return r.optBoolean("completed")?0:r.optLong("positionMs");}
 synchronized void edit(String file,long pos,long duration,boolean done,long timestamp){if(!ProgressRecords.validId(file)||(!own.has(file)&&own.length()>=ProgressRecords.MAX_ENTRIES))return;try{JSONObject previous=merged.optJSONObject(file);if(timestamp!=1&&previous!=null&&previous.optLong("positionMs")==Math.max(0,pos)&&previous.optLong("durationMs")==Math.max(0,duration)&&previous.optBoolean("completed")==done)return;long now=timestamp==1?1:Math.max(System.currentTimeMillis(),previous==null?1:previous.optLong("updatedAt")+1);JSONObject r=new JSONObject().put("positionMs",Math.max(0,pos)).put("durationMs",Math.max(0,duration)).put("completed",done).put("updatedAt",now).put("deviceId",device);own.put(file,r);merged.put(file,new JSONObject(r.toString()));persist();}catch(Exception ignored){}}
 void local(String id,long pos,long duration,boolean done,boolean immediate){synchronized(this){String file=canonical(id);if(file.isEmpty())return;edit(file,pos,duration,done,System.currentTimeMillis());}if(immediate)request(true,null);else request(false,null);}
 void completion(String id,boolean done){JSONObject r; synchronized(this){r=record(id);}local(id,r.optLong("positionMs"),r.optLong("durationMs"),done,true);}
 synchronized JSONObject state(){JSONObject s=new JSONObject(),items=new JSONObject();try{for(Map.Entry<String,String> a:aliases.entrySet()){JSONObject r=merged.optJSONObject(a.getValue());if(r!=null)items.put(a.getKey(),r);}s.put("state",status).put("error",error).put("lastSuccess",lastSuccess).put("accountId",account).put("entries",items);}catch(Exception ignored){}return s;}
 void beforePlay(Runnable action){final int ticket=generation;final boolean[] done={false};Runnable once=()->{if(!done[0]&&ticket==generation){done[0]=true;action.run();}};main.postDelayed(once,5000);request(true,once);}
 void request(boolean force,Runnable finished){main.post(()->{synchronized(this){if(finished!=null)waiters.add(finished);if(running)return;if(!context.getSharedPreferences("drive",0).getBoolean("connected",false)){status="reconnect";finish();return;}long now=System.currentTimeMillis();if(!force&&now-lastAttempt<30000){finish();return;}lastAttempt=now;running=true;status="syncing";error="";}
  final int ticket=generation;AuthorizationRequest auth=AuthorizationRequest.builder().setRequestedScopes(SCOPES).build();Identity.getAuthorizationClient(context).authorize(auth).addOnSuccessListener(result->{if(ticket!=generation)return;if(result.hasResolution()||result.getAccessToken()==null){failed(ticket,"reconnect","Подключите Google Диск заново для синхронизации прогресса");return;}final String token=result.getAccessToken();io.execute(()->exchange(token,ticket));}).addOnFailureListener(e->failed(ticket,"offline","Нет связи. Прогресс сохранён на телефоне"));
 });}
 synchronized void guard(int ticket){if(ticket!=generation||!context.getSharedPreferences("drive",0).getBoolean("connected",false))throw new CancellationException();}
 void exchange(String token,int ticket){try{guard(ticket);JSONObject about=new JSONObject(ProgressSync.http(token,"GET","https://www.googleapis.com/drive/v3/about?fields=user(permissionId)","",""));guard(ticket);String identity=about.getJSONObject("user").getString("permissionId");if(!ProgressRecords.validId(identity))throw new java.io.IOException();JSONObject snapshot;String selected;
  synchronized(this){guard(ticket);if(!identity.equals(account)){JSONObject pending=new JSONObject(own.toString());boolean firstAccount=account.isEmpty()&&!meta.contains("legacyOwner");account=identity;meta.edit().putString("account",account).apply();if(!meta.contains("legacyOwner"))meta.edit().putString("legacyOwner",account).apply();load();ProgressPartition.adopt(own,pending,firstAccount);ProgressRecords.merge(merged,own);persist();}if(account.equals(meta.getString("legacyOwner",""))){for(Map.Entry<String,String> a:new HashMap<>(aliases).entrySet())if(!merged.has(a.getValue())){SharedPreferences old=context.getSharedPreferences("progress",0);long pos=old.getInt(a.getKey(),0);boolean done=old.getStringSet("completedIds",Collections.emptySet()).contains(a.getKey());if(pos>0||done)edit(a.getValue(),pos,0,done,1);}}selected=account;snapshot=new JSONObject(own.toString());}
  ProgressSync.Result result=ProgressSync.exchange(device,snapshot,(m,u,b,t)->{guard(ticket);String response=ProgressSync.http(token,m,u,b,t);guard(ticket);return response;});
  synchronized(this){guard(ticket);if(!selected.equals(account))return;ProgressRecords.merge(own,result.own);ProgressRecords.merge(merged,result.merged);ProgressRecords.merge(merged,own);lastSuccess=System.currentTimeMillis();applyResumePrefs();status=result.rejected>0?"error":"synced";error=result.rejected>0?"Некорректных файлов прогресса пропущено: "+result.rejected:"";persist();}main.post(this::finish);
 }catch(ProgressSync.AuthorizationException e){failed(ticket,"reconnect","Подключите Google Диск заново: нужен доступ к данным приложения");Identity.getAuthorizationClient(context).clearToken(ClearTokenRequest.builder().setToken(token).build());}catch(Exception e){failed(ticket,"offline","Нет связи с Google Диском. Изменения сохранены на телефоне");}}
 synchronized void applyResumePrefs(){SharedPreferences old=context.getSharedPreferences("progress",0);SharedPreferences.Editor edit=old.edit();Set<String> completed=new HashSet<>(old.getStringSet("completedIds",Collections.emptySet()));for(Map.Entry<String,String> a:aliases.entrySet()){JSONObject r=merged.optJSONObject(a.getValue());if(r==null){edit.remove(a.getKey());completed.remove(a.getKey());continue;}edit.putInt(a.getKey(),(int)Math.min(Integer.MAX_VALUE,r.optBoolean("completed")?0:r.optLong("positionMs")));if(r.optBoolean("completed"))completed.add(a.getKey());else completed.remove(a.getKey());}edit.putStringSet("completedIds",completed).apply();}
 void failed(int ticket,String state,String message){synchronized(this){if(ticket!=generation)return;status=state;error=message;}main.post(()->{if(ticket==generation)finish();});}
 synchronized void finish(){running=false;List<Runnable> pending=new ArrayList<>(waiters);waiters.clear();for(Runnable r:pending)main.post(r);}
 synchronized void disconnect(){generation++;running=false;waiters.clear();status="reconnect";error="Подключите Google Диск для синхронизации";}
}
